import type { MetadataRoute } from "next";
import { DEFAULT_THEME, THEME_COLORS } from "@/lib/theme";

/**
 * Web app manifest (doc 02 §12.1). Every icon listed here is generated by a
 * route under src/app/icons. The shortcuts (long press on the app icon) open
 * "Nova transação" through `?novo=` (see QuickAddSheet). Screenshots come
 * later. The splash screen and the status bar before the page loads follow
 * the default theme (dark); the page's <meta name="theme-color"> takes over
 * from there.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Meu Finan",
    short_name: "Meu Finan",
    description: "Controle financeiro pessoal",
    lang: "pt-BR",
    dir: "ltr",
    start_url: "/inicio",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: THEME_COLORS[DEFAULT_THEME],
    theme_color: THEME_COLORS[DEFAULT_THEME],
    categories: ["finance", "productivity"],
    icons: [
      {
        src: "/icons/192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts: [
      {
        name: "Nova despesa",
        url: "/inicio?novo=despesa",
        icons: [{ src: "/icons/sc-despesa.png", sizes: "96x96" }],
      },
      {
        name: "Nova receita",
        url: "/inicio?novo=receita",
        icons: [{ src: "/icons/sc-receita.png", sizes: "96x96" }],
      },
      {
        name: "Extrato",
        url: "/extrato",
        icons: [{ src: "/icons/sc-extrato.png", sizes: "96x96" }],
      },
    ],
  };
}
